/bin/zsh -lc "python3 -B - <<'PY'
import runpy
parse_enabled = runpy.run_path('parser.py')['parse_enabled']
for value in ('true', 'false', '', 'yes', 'True', ' true ', True, 0, None):
    try:
        print(f'{value"'!r} -> {parse_enabled(value)!r}'"')
    except Exception as exc:
        print(f'{value"'!r} -> {type(exc).__name__}: {exc}'"')
PY"

